Public static TFMFilterTreeBuilder Construct(FormTreeControl _tree, FormGroupControl _fgc, FormGroupControl _dataGroup, str _filterNameDelimitation = '')
{
    return new TFMFilterTreeBuilder(_tree,_fgc,_dataGroup, _filterNameDelimitation);
}

public void setButtons(FormButtonControl	_addButton, FormButtonControl	_deleteButton)
{
    addButton = _addButton;
    if (!filterNameDelimitation)
    {
        addButton.registerOverrideMethod(methodstr(formButtonControl, clicked),methodstr(TFMFilterTreeBuilder, add_clicked),this);
    }
    deleteButton = _deleteButton;
    if (!filterNameDelimitation)
    {
        deleteButton.registerOverrideMethod(methodstr(formButtonControl, clicked),methodstr(TFMFilterTreeBuilder, delete_clicked),this);
    }
}

public TreeItemIdx buildTree(int64 _parentKey, TreeItemIdx _parentIdx, int64 _returnIdx = 0)
{
    //FormTreeItem                    formTreeItem;        
    TreeItemIdx                     idx;
    ClassId                         clsId;
    TreeItemIdx                     retIdx = 0;//, tIdx;       
    DictClass                       dc = new DictClass(className2Id(classStr(TFMDocumentHandler)));
    DictClass                       subClass;
    TFMDocumentHandler              docHand;
    //TFMReferenceDataMethodAttribute refDataAttribute = new TFMReferenceDataMethodAttribute();
    List                            extendingClasses = dc.extendedBy(true);
    ListEnumerator                  lEnum = extendingClasses.getEnumerator();

    tree.deleteAll();
    this.resetMaps();
    /*clsId = className2Id(nameOfClass);
    while (lEnum.moveNext())
    {            
        if (clsId && clsId != lEnum.current())
        {
            continue;
        }
        subClass = new DictClass(lEnum.current());
        if (subClass == null ||subClass.isAbstract())
        {
            continue;
        }
        docHand = subClass.makeObject() as TFMDocumentHandler;
        idx = this.addDocumentTreeItem(docHand);

    }*/
    this.addFilterTreeItem();
    addButton.enabled(false);
    return retIdx;
}

private TreeItemIdx addFilterTreeItem()
{
    //TreeItemIdx					idx = this.addTreeItemId(_doc.description(),classIdGet(_doc),classIdGet(_doc),0);
    TreeItemIdx					filterNameIdx;
    SetEnumerator				sEnum;
    TFMRegistrationCollector	regCol;
    int							i, j;
    Set							otherSet;



    if (refData && refData.parmUseDynaFilter())
    {
        i++;
        filterNameIdx  = this.addTreeItemId(refData.parmKey(),i,refData.parmKey(),0);
        filterName =          refData.parmKey();
        sEnum = refData.getCollectors().getEnumerator();
        j = 1;
        while(sEnum.moveNext())
        {
            regCol = sEnum.current();

            this.addFilterFieldTreeItem(refData.parmKey(),filterNameIdx,regCol,refData.parmKey(),i*j*65);
            j++;
        }
    }

    return filterNameIdx;
}

private TreeItemIdx addTreeItemId(Name _name, int64 _id, anytype _data, TreeItemIdx _parentIdx)
{
    FormTreeItem    formTreeItem = new FormTreeItem();
    TreeItemIdx     idx;

    //BP Deviation Documented
    formTreeItem.text(_name);

    formTreeItem.data(_data);
    formTreeItem.image(12209);

    idx = tree.addItem(_parentIdx, 0, formTreeItem);

    id2idx.insert(_id,idx);
    idx2id.insert(idx,_id);

    return idx;
}

public void delete_clicked(FormControl _control)
{
    int currentIdx = tree.getSelection();
    if (idx2parentName.exists(currentIdx))
    {
        TFMFilterAdditions::deleteFilterField(idx2parentName.lookup(currentIdx),idx2fieldName.lookup(currentIdx));
        tree.select(idx2parentIdx.lookup(currentIdx));
        tree.delete(currentIdx);
    }


}

    public void selectionChanged(int _idx, anytype _data)
    {
        SysDictClass					DC;
        //int								i, j;
        //DictMethod						DM;
        //TFMParameterAttribute			parmAttr;
        //Map								filters = TFMFormLookupHelper::getConfigurableFilters();
        SetEnumerator					collectors;
        TFMReferenceDataConfiguration	filterConfig;
        anytype							filterObject;
        TFMRegistrationCollector		collector;
        FormStringControl				formStringControl;
        FormCheckBoxControl				chkcontrol;
        FormComboBoxControl				comboBox;
        FormInt64Control				intControl;
        //Array							array;
        str								filterStr, clsName, mthdName;
        Map								controls;
        MapEnumerator					mEnum;
        FormControl						control;
        deleteButton.enabled(false);
        addButton.enabled(false);
        dataGroup.enabled(false);
        dataGroup.visible(false);
        fgc.columns(1);

        while (fgc.controlCount())
        {
            fgc.formRun().design().removeControl(fgc.controlNum(1).id());
        }


        if (typeOf(_data) == Types::Class && TFMHelper::List2Set(new SysDictClass(classNum(TFMRegistrationCollector)).extendedBy(true)).in(classidget(_data)))
        {
            collector  = _data;
            controls = collector.PopulateGroup(fgc, false,false,'','',null,false);
            fgc.columns(2);
            mEnum = controls.getEnumerator();
			while (mEnum.moveNext())
            {
                control = mEnum.currentValue();
                if (classIdGet(control) == classNum(FormStringControl))
                {
                    formStringControl = control;
                    formStringControl.registerOverrideMethod(methodStr(FormStringControl,modified), methodStr(TFMFilterTreeBuilder, control_modified),this);
                }
                else if (classIdGet(control) == classNum(FormCheckBoxControl))
                {
                    chkcontrol = control;
                    chkcontrol.registerOverrideMethod(methodStr(FormCheckBoxControl,modified), methodStr(TFMFilterTreeBuilder, control_modified),this);
                }
                else if (classIdGet(control) == classNum(FormComboBoxControl))
                {
                    comboBox = control;
                    comboBox.registerOverrideMethod(methodStr(FormComboBoxControl,modified), methodStr(TFMFilterTreeBuilder, control_modified),this);
                }
                else if (classIdGet(control) == classNum(FormInt64Control))
                {
                    intControl = control;
                    intControl.registerOverrideMethod(methodStr(FormInt64Control,modified), methodStr(TFMFilterTreeBuilder, control_modified),this);
                }
            }
            if (idx2parentName.exists(tree.getSelection()))
            {
                deleteButton.enabled(TFMFilterAdditions::exist(idx2parentName.lookup(tree.getSelection()),idx2fieldName.lookup(tree.getSelection())));
                //dataGroup.enabled(TFMFilterAdditions::exist(idx2parentName.lookup(tree.getSelection()),idx2fieldName.lookup(tree.getSelection())));
                //dataGroup.visible(dataGroup.enabled());
                dataGroup.enabled(true);
                dataGroup.visible(dataGroup.enabled());
                fgc.enabled(deleteButton.enabled());
            }
            //deleteButton.enabled(true);
            return;
        }
        addButton.enabled(false);
        deleteButton.enabled(false);
        filterStr = _data;

        filterConfig = headers.exists(filterStr) ? headers.lookup(filterStr) : null;
        if (!filterConfig)
        {
            return;
        }
        filterName = filterConfig.parmKey() ? filterConfig.parmKey() : mthdName;
        filterConfig.parmKey(filterName);
        collectors = filterConfig.getCollectors().getEnumerator();
        while (collectors.moveNext())
        {
            collector = collectors.current();
            formStringControl = fgc.addControl(FormControlType::String,collector.parmName());
            formStringControl.allowEdit(false);
            formStringControl.label(collector.parmLabel());
        }

        addButton.enabled(true);

    }

    public boolean control_modified(FormControl _control)
    {
        //Info (_control.name() + ' modified');
        MethodName					callMethod = SysTest::hasMethod(_control,methodStr(FormCheckBoxControl, value)) ? methodStr(FormCheckBoxControl, value) : methodStr(FormControl, valueStr);
        TFMRegistrationCollector	regCollector;
        anytype						treeData = tree.getItem(tree.getSelection()).data();
        TFMFilterFieldValues::addValue(idx2parentName.lookup(tree.getSelection()),idx2fieldName.lookup(tree.getSelection()),_control.name(),new SysDictClass(classIdGet(_control)).callObject(callMethod,_control));

        if (typeOf(treeData) == Types::Class && new SysDictClass(classIdGet(treeData)).extend() == classNum(TFMRegistrationCollector))
        {
			regCollector = treeData;
            TFMFilterFieldValues::addSavedValuesToCollector(idx2parentName.lookup(tree.getSelection()),idx2fieldName.lookup(tree.getSelection()),regCollector);

        }
        return true;
    }

