    private TreeItemIdx addDocumentTreeItem(TFMDocumentHandler _doc)
    {
        TreeItemIdx					idx = this.addTreeItemId(_doc.description(),classIdGet(_doc),classIdGet(_doc),0);
        TreeItemIdx					/*filterIdx, pagesIdx, flowsIdx, parmsIdx,*/ filterNameIdx;//, filterFieldNameIdx;
        SetEnumerator				sEnum;
        SysDictClass				DC = new SysDictClass(classIdGet(_doc));

        //DictMethod					DM;
        //TFMParameterAttribute		parmAttr;
        //Array						array;
        TFMRegistrationCollector	regCol;
        int							i, j;
        boolean						foundOne;
        Set							methodSet = _doc.getReferenceDataMethods();
        Set							otherSet;
        MapEnumerator				mEnum;
        //str							isCustom;
        if (methodSet == null)
        {
            methodSet = new Set(Types::String);
        }
        otherSet = new Set(Types::String);
        mEnum = TFMAttributeHandler::getMethodNamesFromSysAttribute(classIdGet(_doc),new TFMReferenceDataMethodAttribute()).getEnumerator();
		while (mEnum.moveNext())
        {
            otherSet.add(mEnum.currentKey());
        }
        methodSet = Set::union(methodSet,otherSet);
        foundOne = false;
        if (methodSet.elements())
        {            
            sEnum  = methodSet.getEnumerator();
            while (sEnum.moveNext())
            {
                i++;
                if (configFilters.exists(DC.name() + '.' + sEnum.current() + '()') && (!filterNameDelimitation || filterNameDelimitation == sEnum.current()))
                {
                    filterNameIdx  = this.addTreeItemId(sEnum.current(),i,DC.name() + '.' + sEnum.current(),idx);
                    idx2className.insert(filterNameIdx,DC.name());
                    mEnum = TFMFormLookupHelper::getConfigurableFilterFields(DC.name() + '.' + sEnum.current()).getEnumerator();
                    j = 1;
					while(mEnum.moveNext())
                    {
                        regCol = mEnum.currentValue();
                        /*isCustom = TFMFilterAdditions::exist(sEnum.current(),regCol.parmName()) ? ' {Custom}' :'';

                        filterFieldNameIdx = this.addTreeItemId(mEnum.currentKey() + ' (' + subStr(classId2Name(classIdGet(regCol)),strLen(classStr(TFMRegistrationCollector))+1,strLen (classId2Name(classIdGet(regCol)))) +')'+isCustom,j*i*65,mEnum.currentValue(),filterNameIdx);
                        idx2fieldName.insert(filterFieldNameIdx,regCol.parmName());
                        idx2parentName.insert(filterFieldNameIdx,sEnum.current());
                        idx2className.insert(filterFieldNameIdx,DC.name());*/
                        this.addFilterFieldTreeItem(sEnum.current(),filterNameIdx,regCol,DC.name(),i*j*65);
                        j++;
                    }
                    foundOne = true;
                }				
            }            
        }
        nextID = i*j*65;

        if (!foundOne)
        {
            tree.delete(idx);
        }
        return idx;
    }

private void addFilterFieldTreeItem(MethodName _filterName, int _parentIdx, TFMRegistrationCollector	_regCol, ClassName _className, int _id)
{
    str isCustom = TFMFilterAdditions::exist(_filterName,_regCol.parmName()) ? ' {Custom}' :'';

    int filterFieldNameIdx = this.addTreeItemId(_regCol.parmName() + ' (' + subStr(classId2Name(classIdGet(_regCol)),strLen(classStr(TFMRegistrationCollector))+1,strLen (classId2Name(classIdGet(_regCol)))) +')'+isCustom,_id,_regCol,_parentIdx);
    idx2fieldName.insert(filterFieldNameIdx,_regCol.parmName());
    idx2parentName.insert(filterFieldNameIdx,_filterName);
    idx2className.insert(filterFieldNameIdx,_className);
    idx2parentIdx.insert(filterFieldNameIdx,_parentIdx);
}

public void add_clicked(FormControl _control, TableName _tableName = '')
{
    dialog		                    dialog = new dialog();
    DialogField                     dialogFLD = _tableName ? dialog.addField(extendedTypeStr(FieldName)) : dialog.addField(extendedTypeStr(ExtendedDataTypeName));
    str			                    EDTName;
    ExtendedTypeId                  edtId;
    TFMFilterAdditionsDataBinding   TFMFilterAdditionsDataBinding;

    dialog.caption("@SYS329055");
    if (_tableName)
    {
        dialogFLD.registerOverrideMethod(methodStr(FormStringControl,lookup), methodStr(TFMFilterTreeBuilder,lookupFields),this);
        tableName = _tableName;
    }
    dialog.run();

    if(!dialog.closedOk())
    {
        return;
    }
    EDTName = dialogFLD.value();

    if (_tableName)
    {
        edtId = new SysDictField(tableName2Id(_tableName),fieldName2Id(tableName2Id(_tableName),EDTName)).typeId();
        if(!edtId)
        {
            Error ("@TFM:IncompatibleField");
        }
        TFMFilterAdditionsDataBinding.FieldName = EDTName;
        EDTName = extendedTypeId2name(edtId);
        TFMFilterAdditionsDataBinding.FilterName = filterName;
        TFMFilterAdditionsDataBinding.FilterFieldName = EDTName;
        //TFMFilterAdditionsDataBinding.ClassName = this.currentClassName();
        TFMFilterAdditionsDataBinding.TableName = _tableName;

        TFMFilterAdditionsDataBinding.insert();

    }

    TFMFilterAdditions::AddFilterField(filterName,EDTName,EDTName);

    nextID++;
    this.addFilterFieldTreeItem(filterName,tree.getSelection(),TFMRegistrationCollector::collectorFromEDT(EDTName),filterName,nextID);
}

public void lookupFields(FormControl _formControl)
{
    TFMFormLookupHelper::lookupTableFieldNamesWithEDT(tableName, _formControl);
}

public boolean expanding(TreeItemIdx _idx, FormTreeExpand _action, anytype _data)
{
    boolean ret;
    FormTreeItem item = tree.getItem(_idx);

    if (!item.stateExpandedOnce())
    {
        this.buildTree(item.data(), _idx);
        //ret = super(_idx, _action, _data);
    }
    return ret;
}
